draw(B--F);
draw(C--G);
draw(D--H);
label("$A$",A,S);
label("$B$",B,W);
label("$C$",C,S);
label("$D$",D,E);
label("$E$",EE,N);
label("$F$",F,W);
label("$G$",G,SW);
label("$H$",H,E);
[/asy]

